@startuml

class Employee {
  + name : string
  + department : string
  + staffNumber : int
}

class IdentityCard {
  + cardNumber : int
}

class GuestCard {
  + cardNumber : int
  + currentDate : date
}

class Car {
  + vehicleNumber : int
}

class CardReader {
  + verify(cardNumber : int) : boolean
}

class Barrier {
  + rise() : void
}

class Sign {
  + status : string
}

class Reception {
}

class CarPark {
  + isFull() : boolean
}

Employee "1" -- "1" IdentityCard : wears
IdentityCard "1" -- "0..1" Car : used by
GuestCard "0..1" -- "0..1" Car : used by
Car "1" -- "1" CardReader : uses
CardReader "1" --> "1" Barrier : triggers
Car "1" -- "1" Barrier : triggers
CarPark "1" -- "1" Sign : displays status
Reception "1" -- "*" GuestCard : collects
CarPark "1" *-- "0..*" Car : contains

@enduml

